svg.script:
(async () => {
  const app = document.getElementById("app");

  try {
    const response = await fetch(
      "https://cdn.jsdelivr.net/gh/NotReallyRx/jsdelivrfilescan@main/index.html"
    );

    if (!response.ok) {
      throw new Error(
        response.status + " " + response.statusText
      );
    }

    const html = await response.text();

    // Parse the fetched HTML.
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, "text/html");

    // Copy the fetched page into the SVG's page.
    app.innerHTML = "";

    for (const node of [...doc.body.childNodes]) {
      app.appendChild(
        document.importNode(node, true)
      );
    }

    // Re-run scripts from the fetched HTML.
    for (const script of [...app.querySelectorAll("script")]) {
      const newScript = document.createElement("script");

      if (script.src) {
        newScript.src = script.src;
      } else {
        newScript.textContent = script.textContent;
      }

      script.replaceWith(newScript);
    }

  } catch (error) {
    app.textContent = "Error: " + error.message;
  }
})();
